		me:AddMsg(XT("陈佳宁突然呼吸急促，面红耳赤，原来是鼻炎犯了，只见她张嘴呼吸，[NAME]从中领悟了一些奥秘。"));
		me:AddModifier("Story_LingAbsorbSpeed1");
	elseif nR == 3 then
		me:AddMsg(XT("陈佳宁突然御剑飞行，在空中画出了一道妙曼的弧线，[NAME]领悟了一些飞行诀窍。"));
		me:AddModifier("Story_WorldMapFlySpeedAddP1");
	elseif nR == 4 then
		me:AddMsg(XT("陈佳宁传授了[NAME]一套金刚护体功法，[NAME]的运气还真是不错呢。"));
		me:AddModifier("Story_ShieldConversionRate1");
	end
else
	me:AddMsg(XT("[NAME]蠢的一比，看陈佳宁耍了半天什么都没学会,还把自己弄伤了。"));
	me:AddDamgeFromCache(story.DamageCache, 4);
end

